//! Writes the generated TypeScript: tauri-specta's single export is cut into
//! `packages/core/src/generated/types.ts` (types and constants, no Tauri import, shared by
//! every app) and `src/desktop-transport/commands.ts` (the desktop's `commands` and
//! `events`), and each half is checked before it is written. Also writes the tray rate
//! table. Generated files are never hand-edited; see `.claude/rules/generated-bindings.md`.

use std::path::PathBuf;

use anyhow::Context;
use specta_typescript::Typescript;
use tauri_specta::Builder;

/// Where the generated TypeScript types and constants land, with no Tauri import so
/// every app can use them.
pub const TYPES_PATH: &str = concat!(
    env!("CARGO_MANIFEST_DIR"),
    "/../packages/core/src/generated/types.ts"
);

/// Where the generated Tauri `commands` and `events` land. Desktop only.
pub const COMMANDS_PATH: &str = concat!(
    env!("CARGO_MANIFEST_DIR"),
    "/../src/desktop-transport/commands.ts"
);

/// The tray's rate strings for sample inputs, written with the bindings so
/// `bindings-check` fails when the preview's test would check a stale table.
pub const TRAY_RATES_PATH: &str = concat!(
    env!("CARGO_MANIFEST_DIR"),
    "/../packages/core/src/generated/tray-rates.json"
);

/// The module `commands.ts` imports the generated types from.
const TYPES_MODULE: &str = "@core/generated/types";

const GENERATED_HEADER: &str =
    "// This file has been generated by Tauri Specta. Do not edit this file manually.\n";
const COMMANDS_MARKER: &str = "/** Commands */";
const CONSTANTS_MARKER: &str = "/* Constants */";
const RUNTIME_MARKER: &str = "/* Tauri Specta runtime */";

/// Text that means Tauri code leaked into the shared types file.
const TYPES_FORBIDDEN: [&str; 4] = [
    "@tauri-apps",
    "__TAURI_",
    "export const commands",
    "export const events",
];
/// Text the commands file must hold.
const COMMANDS_REQUIRED: [&str; 2] = ["export const commands = {", "export const events = {"];
/// Text that means type declarations leaked into the commands file.
const COMMANDS_FORBIDDEN: [&str; 1] = ["export type "];

/// Writes the TypeScript bindings for `builder`, split into [`TYPES_PATH`] and
/// [`COMMANDS_PATH`], and the tray rate table to [`TRAY_RATES_PATH`].
///
/// # Errors
///
/// Fails when the export or a write fails, or when tauri-specta's output no longer splits
/// into a Tauri-free types file and a commands file (its layout changed).
pub fn export_bindings(builder: &Builder<tauri::Wry>) -> anyhow::Result<()> {
    let exported = export_to_string(builder)?;
    let split = split_bindings(&exported)?;
    std::fs::write(TYPES_PATH, split.types)
        .with_context(|| format!("writing generated types to {TYPES_PATH}"))?;
    std::fs::write(COMMANDS_PATH, split.commands)
        .with_context(|| format!("writing generated commands to {COMMANDS_PATH}"))?;
    let rates = || format!("writing the tray rate table to {TRAY_RATES_PATH}");
    let golden =
        serde_json::to_string_pretty(&crate::tray::model::rate_golden()).with_context(rates)?;
    std::fs::write(TRAY_RATES_PATH, golden + "\n").with_context(rates)?;
    Ok(())
}

/// A scratch file removed when dropped, so no return path leaves it behind.
struct ScratchFile(PathBuf);

impl Drop for ScratchFile {
    fn drop(&mut self) {
        match std::fs::remove_file(&self.0) {
            Err(err) if err.kind() != std::io::ErrorKind::NotFound => {
                eprintln!(
                    "could not remove scratch export {}: {err}",
                    self.0.display()
                );
            }
            _ => {}
        }
    }
}

/// Runs tauri-specta's export into a scratch file and returns its text with trailing
/// whitespace removed from every line.
///
/// tauri-specta rc.25 only exports to a path, so the scratch file stands in for an
/// export to a string.
fn export_to_string(builder: &Builder<tauri::Wry>) -> anyhow::Result<String> {
    let scratch = ScratchFile(
        std::env::temp_dir().join(format!("statglass-bindings-{}.ts", std::process::id())),
    );
    let exporting = || format!("exporting bindings to {}", scratch.0.display());
    builder
        .export(Typescript::default(), &scratch.0)
        .with_context(exporting)?;
    let exported = std::fs::read_to_string(&scratch.0).with_context(exporting)?;
    // Specta emits spaces after union separators. Normalize generation itself so
    // freshly added variants pass the repository whitespace gate reproducibly.
    Ok(exported
        .lines()
        .map(str::trim_end)
        .collect::<Vec<_>>()
        .join("\n")
        + "\n")
}

/// The two files cut from one tauri-specta export.
struct SplitBindings {
    /// Every type and constant; no Tauri import.
    types: String,
    /// `commands`, `events` and the runtime they call, importing the types they name.
    commands: String,
}

/// Cuts a tauri-specta export into types and constants, and commands and events.
///
/// The export is laid out as imports, commands, events, constants, types, then the
/// runtime helpers; the cut follows the section comments tauri-specta writes, and each
/// half is checked for what it must and must not hold.
///
/// # Errors
///
/// Fails when a section comment is missing or out of order, or a half holds the wrong
/// code, which means the generator's layout changed and this split needs updating.
fn split_bindings(exported: &str) -> anyhow::Result<SplitBindings> {
    let (imports, rest) = split_before(exported, COMMANDS_MARKER)?;
    let (api, rest) = split_before(rest, CONSTANTS_MARKER)?;
    let (declarations, runtime) = split_before(rest, RUNTIME_MARKER)?;
    let names = type_names_used_by(declarations, &[api, runtime]);
    let types = format!("{GENERATED_HEADER}\n{}\n", declarations.trim_end());
    let commands = format!(
        "{}\nimport type {{ {} }} from \"{TYPES_MODULE}\";\n\n{api}{runtime}",
        imports.trim_end(),
        names.join(", "),
    );
    check_contents("types.ts", &types, &[], &TYPES_FORBIDDEN)?;
    check_contents(
        "commands.ts",
        &commands,
        &COMMANDS_REQUIRED,
        &COMMANDS_FORBIDDEN,
    )?;
    Ok(SplitBindings { types, commands })
}

/// Splits `text` at the start of `marker`, keeping the marker in the second half.
fn split_before<'a>(text: &'a str, marker: &str) -> anyhow::Result<(&'a str, &'a str)> {
    let at = text.find(marker).with_context(|| {
        format!(
            "tauri-specta output has no `{marker}` section after the previous one; \
             update src-tauri/src/bindings.rs for its layout"
        )
    })?;
    Ok(text.split_at(at))
}

/// Checks that the generated file `name` holds every `required` text and no `forbidden`
/// one.
fn check_contents(
    name: &str,
    text: &str,
    required: &[&str],
    forbidden: &[&str],
) -> anyhow::Result<()> {
    if let Some(missing) = required.iter().find(|needle| !text.contains(**needle)) {
        anyhow::bail!(
            "generated {name} lacks `{missing}`; tauri-specta's layout changed, \
             update src-tauri/src/bindings.rs"
        );
    }
    if let Some(found) = forbidden.iter().find(|needle| text.contains(**needle)) {
        anyhow::bail!(
            "generated {name} contains `{found}`; tauri-specta's layout changed, \
             update src-tauri/src/bindings.rs"
        );
    }
    Ok(())
}

/// The names of the types exported by `declarations` that appear in the code (not the
/// doc comments) of any of `users`, in declaration order.
fn type_names_used_by(declarations: &str, users: &[&str]) -> Vec<String> {
    let is_ident = |c: char| c.is_ascii_alphanumeric() || c == '_';
    // A name only a comment mentions would be an unused import, which tsc rejects.
    let is_comment = |line: &&str| {
        let line = line.trim_start();
        line.starts_with("/*") || line.starts_with('*') || line.starts_with("//")
    };
    let used: std::collections::HashSet<&str> = users
        .iter()
        .flat_map(|text| text.lines())
        .filter(|line| !is_comment(line))
        .flat_map(|line| line.split(|c: char| !is_ident(c)))
        .collect();
    declarations
        .lines()
        .filter_map(|line| line.strip_prefix("export type "))
        .map(|rest| {
            rest.chars()
                .take_while(|&c| is_ident(c))
                .collect::<String>()
        })
        .filter(|name| used.contains(name.as_str()))
        .collect()
}

#[cfg(test)]
mod bindings_tests {
    use super::{TYPES_MODULE, export_to_string, split_bindings};
    use crate::specta_builder;

    #[test]
    fn real_export_splits_into_tauri_free_types_and_commands_naming_their_types() {
        let exported = export_to_string(&specta_builder()).unwrap();
        let split = split_bindings(&exported).unwrap();

        assert!(split.types.contains("export type LiveMsg ="));
        assert!(split.types.contains("export const CHART_WINDOWS ="));
        assert!(split.commands.contains("function makeEvent<T>"));
        let types_import = split
            .commands
            .lines()
            .find(|line| line.ends_with(&format!("from \"{TYPES_MODULE}\";")))
            .expect("commands.ts imports the generated types");
        for name in ["LiveMsg", "CommandError", "DockerSnapshot"] {
            assert!(
                types_import.contains(&format!(" {name},")),
                "{name} not imported"
            );
        }
        assert!(
            !types_import.contains(" UsageTotal,"),
            "unused type imported"
        );
    }

    #[test]
    fn events_after_constants_are_rejected() {
        let export = "/** Commands */\nexport const commands = {};\n/* Constants */\n\
                      /** Events */\nexport const events = {};\nexport type A = number;\n\
                      /* Tauri Specta runtime */\n";
        let error = split_bindings(export).err().expect("events in types.ts");
        assert_eq!(
            error.to_string(),
            "generated types.ts contains `export const events`; tauri-specta's layout \
             changed, update src-tauri/src/bindings.rs"
        );
    }

    #[test]
    fn types_after_the_runtime_are_rejected() {
        let export = "/** Commands */\nexport const commands = {};\n/** Events */\n\
                      export const events = {};\n/* Constants */\n/* Tauri Specta runtime */\n\
                      function makeEvent() {}\nexport type A = number;\n";
        let error = split_bindings(export).err().expect("types in commands.ts");
        assert_eq!(
            error.to_string(),
            "generated commands.ts contains `export type `; tauri-specta's layout \
             changed, update src-tauri/src/bindings.rs"
        );
    }

    #[test]
    fn a_missing_section_is_named() {
        let error = split_bindings("export type A = number;\n")
            .err()
            .expect("no sections");
        assert!(error.to_string().contains("`/** Commands */`"), "{error}");
    }
}
